172	  // Category 1: Relic (45% chance)
173	  if (categoryRoll < 0.45) {
174	    const prefix = SAMPLE_RELIC_PREFIXES[Math.floor(Math.random() * SAMPLE_RELIC_PREFIXES.length)];
175	    const noun = SAMPLE_RELIC_NOUNS[Math.floor(Math.random() * SAMPLE_RELIC_NOUNS.length)];
176	    const name = `${prefix} ${noun}`;
177	
178	    const scoreMultiplier = { common: 2.0, uncommon: 4.0, rare: 6.0, epic: 8.0, legendary: 10.0 }[chosenRarity];
179	    const score = Math.round((Math.random() * 2.0 + scoreMultiplier) * 100) / 100;
180	
181	    const rank = chosenRarity === 'legendary' ? '✦'
182	      : chosenRarity === 'epic' ? 'Ψ'
183	      : chosenRarity === 'rare' ? 'S₁'
184	      : chosenRarity === 'uncommon' ? 'A+'
185	      : 'B';
186	
187	    const atk = Math.floor(Math.random() * 15 * scoreMultiplier);
188	    const def = Math.floor(Math.random() * 12 * scoreMultiplier);
189	    const spd = Math.floor(Math.random() * 10 * scoreMultiplier);
190	    const luck = Math.floor(Math.random() * 8 * scoreMultiplier);
191	
192	    const downsideSeverity = Math.floor(Math.random() * 3) + 1;
193	    const downsidePenalty = downsideSeverity * 3;
194	
195	    return {
196	      id,
197	      name,
198	      description: `Double-edged ancient armament summoned from the ${TICKET_REGISTRY[ticketType].name}. Bestows tremendous power with a binding penalty.`,
199	      category: 'relic',
200	      rarity: chosenRarity,
201	      rank,
202	      score,
203	      origin: ticketType,
204	      iconEmoji: '⚔️',
205	      stats: [
206	        { name: 'ATK', value: atk },
207	        { name: 'DEF', value: def },
208	        { name: 'SPD', value: spd - downsidePenalty },
209	        { name: 'LUCK', value: luck },
210	      ],
211	      buffs: [
212	        {
213	          name: `${prefix} Resonance`,
214	          description: `Boosts Golden Hour yield multiplier by +${(scoreMultiplier * 2.5).toFixed(1)}%.`,
215	          magnitude: scoreMultiplier * 0.025,
216	        },
217	      ],
218	      downsides: [
219	        {
220	          name: `Curse of ${prefix}`,
221	          description: `Reduces combat movement speed by -${downsidePenalty} and increases stamina drain.`,
222	          severity: downsideSeverity,
223	        },
224	      ],
225	      pulledAt: new Date().toISOString(),
226	    };
227	  }
228	
229	  // Category 2: Collectible (30% chance)
230	  if (categoryRoll < 0.75) {
231	    const template = SAMPLE_COLLECTIBLES[Math.floor(Math.random() * SAMPLE_COLLECTIBLES.length)];
232	    const scoreMultiplier = { common: 1.5, uncommon: 3.5, rare: 5.5, epic: 7.5, legendary: 9.5 }[chosenRarity];
233	    const score = Math.round((Math.random() * 1.5 + scoreMultiplier) * 100) / 100;
234	
235	    const rank = chosenRarity === 'legendary' ? 'Ø'
236	      : chosenRarity === 'epic' ? 'Ψ'
237	      : chosenRarity === 'rare' ? 'S₂'
238	      : chosenRarity === 'uncommon' ? 'A'
239	      : 'C';
