3	import React, { useState, useEffect } from 'react';
4	import type { RawDeckPack } from '../../packs';
5	import { Sparkles, Ticket } from 'lucide-react';
6	import './gachaStyles.css';
7	
8	interface GachaLobbyProps {
9	  cardpacks: RawDeckPack[];
10	  totalDict: Record<string, number>;
11	  totalPackOpened: number;
12	  ticketBalances: Record<string, number>;
13	  onRoll: (deck: RawDeckPack) => void;
14	}
15	
16	export const GachaLobby: React.FC<GachaLobbyProps> = ({
17	  cardpacks,
18	  totalDict,
19	  totalPackOpened,
20	  ticketBalances,
21	  onRoll,
22	}) => {
23	  const [activeCard, setActiveCard] = useState<number | null>(null);
24	  const [hoveredCard, setHoveredCard] = useState<number | null>(null);
25	  const [hoveringEffect, setHoveringEffect] = useState<number | string>('none');
26	
27	  // Handle card click toggle
28	  const handleCardClick = (index: number) => {
29	    setActiveCard((prev) => (prev === index ? null : index));
30	    setHoveringEffect((prev) => (prev === index ? 'none' : index));
31	  };
32	
33	  // Click outside listener to deselect active card
34	  useEffect(() => {
35	    const handleClickOutside = (e: MouseEvent) => {
36	      const target = e.target as HTMLElement;
37	      if (!target.closest('.card')) {
38	        setActiveCard(null);
39	      }
40	    };
41	
42	    document.addEventListener('click', handleClickOutside);
43	    return () => document.removeEventListener('click', handleClickOutside);
44	  }, []);
45	
46	  return (
47	    <div className="relative w-full space-y-6">
48	      {/* 📊 Top-Right Real-Time Hover HUD Telemetry */}
49	      {hoveredCard !== null && (
50	        <div className="total-dict">
51	          <div className="flex items-center justify-between pb-2 mb-2 border-b border-white/10 text-xs font-mono text-[#ffd86b]">
52	            <span className="flex items-center gap-1.5">
53	              <Sparkles className="w-3.5 h-3.5" />
54	              <strong>Unboxed Archives</strong>
55	            </span>
56	            <span className="text-[10px] text-[#9c93a8]">Lifetime Pulls</span>
57	          </div>
58	
59	          <div className="total-dict-list">
60	            {Object.entries(totalDict).length === 0 && (
61	              <div className="text-xs text-[#8c7a9e] py-2 text-center font-mono">No items pulled yet</div>
62	            )}
63	            {Object.entries(totalDict)
64	              .sort(([, a], [, b]) => b - a)
65	              .map(([key, value]) => (
66	                <div key={key} className="total-dict-item">
67	                  <strong title={key}>{key}:</strong>
68	                  <span className="font-bold text-white bg-[#1c1424] px-1.5 py-0.5 rounded border border-[#3b304f]">
69	                    {value}
70	                  </span>
71	                </div>
72	              ))}
73	          </div>
74	
75	          <div className="pt-2 border-t border-white/10 flex items-center justify-between text-xs font-mono">
76	            <span className="text-[#8c7a9e]">Packs Opened:</span>
77	            <strong className="text-[#38bdf8] text-sm">{totalPackOpened}</strong>
78	          </div>
79	        </div>
80	      )}
81	
82	      {/* 🃏 Card Packs Grid Container (Centered) */}
83	      <div className="cards-container">
84	        {cardpacks.map((card, index) => {
85	          const isSelected = activeCard === index;
86	          const isHovered = hoveredCard === index;
87	          const availableTickets = ticketBalances[card.cost.currency] || 0;
88	          const canAfford = availableTickets >= card.cost.amount;
89	          const buttonLabel = card.visuals.button_text || 'Engage';
90	
91	          // Image asset swap on hover or active selection
92	          const imageSrc =
93	            isHovered || isSelected || hoveringEffect === index
94	              ? card.visuals.preview_url || card.visuals.cover_url
95	              : card.visuals.cover_url;
96	
97	          return (
98	            <div
99	              className={`card ${isSelected ? 'active' : ''}`}
100	              key={card.id || index}
101	              onClick={() => handleCardClick(index)}
102	              onMouseEnter={() => {
103	                setHoveredCard(index);
104	                setHoveringEffect(activeCard === index ? index : index);
105	              }}
106	              onMouseLeave={() => {
107	                setHoveredCard(null);
108	                setHoveringEffect('none');
109	              }}
110	            >
111	              {/* Pack Image Container */}
112	              <div className="card-img-wrapper">
113	                <img
114	                  src={imageSrc}
115	                  alt={card.title}
116	                  loading="lazy"
117	                  onError={(e) => {
118	                    (e.target as HTMLImageElement).src =
119	                      'https://images.unsplash.com/photo-1518709268805-4e9042af9f23?w=500&auto=format&fit=crop&q=80';
120	                  }}
121	                />
122	
123	                {/* Cards Per Pack Badge */}
124	                <div className="absolute top-3 right-3 px-2.5 py-1 rounded-lg bg-[#120f18]/85 border border-[#d4af37]/60 text-[11px] font-mono font-bold text-[#ffd86b] shadow-lg backdrop-blur-md">
125	                  {card.cards_per_pull} Cards
126	                </div>
127	
128	                {/* Ticket / Disc Cost Badge */}
129	                <div className="absolute top-3 left-3 px-2.5 py-1 rounded-lg bg-[#120f18]/85 border border-white/20 text-[11px] font-mono text-white flex items-center gap-1 shadow-lg backdrop-blur-md">
130	                  <Ticket className="w-3 h-3 text-[#ffd86b]" />
131	                  <span>{card.cost.amount} {card.cost.currency === 'discs' ? 'DISCS' : card.cost.currency.split('-')[0].toUpperCase()}</span>
132	                </div>
133	              </div>
134	
135	              {/* Pack Body (Centered Horizontally) */}
136	              <div className="card-body">
137	                <div className="w-full text-center">
138	                  <div className="card-title">
139	                    <span>{card.title}</span>
140	                  </div>
141	                  <div className="text-[11px] font-mono text-[#8c7a9e] mt-1 text-center">
142	                    Available: <strong className={canAfford ? 'text-emerald-400' : 'text-rose-400'}>{availableTickets}</strong>
143	                  </div>
144	                </div>
145	
146	                {/* Pack Footer */}
147	                <div className="card-footer">
148	                  <div
149	                    className="card-note"
150	                    style={{
151	                      '--note-color': isSelected || isHovered ? 'transparent' : '#9c93a8',
152	                    } as React.CSSProperties}
153	                  >
154	                    <i>{card.subtitle}</i>
155	                  </div>
156	
157	                  {(isSelected || isHovered) && (
158	                    <div className="button-row" onClick={(e) => e.stopPropagation()}>
159	                      <button
160	                        className="card-button"
161	                        disabled={!canAfford}
162	                        style={{
163	                          backgroundColor: canAfford ? (card.visuals.accent_color || '#ffd86b') : undefined,
164	                        }}
