166	                      >
167	                        <Sparkles className="w-4 h-4" />
168	                        <span>{canAfford ? buttonLabel : 'Need Tickets'}</span>
169	                      </button>
170	                    </div>
171	                  )}
172	                </div>
173	              </div>
174	            </div>
175	          );
176	        })}
177	      </div>
178	    </div>
179	  );
180	};
