// -----------------------------------------------------------------------
// PULL PACK BATCH (High-Efficiency Multi-Pull Engine)
// -----------------------------------------------------------------------
pullPackBatch: (deck: RawDeckPack, multiplier: number = 1) => {
  const inv = useInventoryStore.getState();
  const mult = Math.max(1, multiplier);
  const totalCost = deck.cost.amount * mult;
  const currency = deck.cost.currency;

  // 1. Check ticket or disc currency availability and consume
  let hasTicket = false;
  if (currency === 'angel-roll' && inv.angelRollTickets >= totalCost) {
    inv.spendAngelTickets(totalCost);
    hasTicket = true;
  } else if (currency === 'solar-roll' && inv.solarRollTickets >= totalCost) {
    inv.spendSolarTickets(totalCost);
    hasTicket = true;
  } else if (currency === 'codex-roll' && inv.codexRollTickets >= totalCost) {
    inv.spendCodexTickets(totalCost);
    hasTicket = true;
  } else if (currency === 'discs') {
    const vinylDiscs = useVinylStore.getState().discs || inv.discs || 0;
    if (vinylDiscs >= totalCost) {
      inv.spendDiscs(totalCost);
      useVinylStore.getState().spendDiscs(totalCost);
      hasTicket = true;
    }
  } else if (currency === 'shredder-ticket' && inv.shredderTickets >= totalCost) {
    inv.spendShredderTickets(totalCost);
    hasTicket = true;
  } else if (inv.shredderTickets >= totalCost) {
    // Universal fallback: Shredder tickets can open ANY card pack!
    inv.spendShredderTickets(totalCost);
    hasTicket = true;
  }

  if (!hasTicket) {
    return null;
  }

  // 2. Execute multi-roll via compiled engine
  const { items, dict } = executePackRoll(deck, mult);

  // 3. Inject energy cores if any & accumulate cross-app resources
  let newReserves = { ...get().energyReserves };
  let totalDnaReward = 0;
  let totalRedOrbsReward = 0;
  let totalTimeRewardSeconds = 0;

  for (const item of items) {
    if (item.category === 'energy-core' && item.energyCores) {
      for (const core of item.energyCores) {
        newReserves[core.attribute] = (newReserves[core.attribute] || 0) + core.amount;
      }
    }

