                  canAffordShredder
                    ? 'bg-gradient-to-r from-blue-600 via-amber-500 to-red-600 hover:from-blue-500 hover:via-amber-400 hover:to-red-500 text-white shadow-amber-500/20 active:scale-[0.98]'
                    : 'bg-[#1c1826] text-slate-500 border border-slate-700/60 cursor-not-allowed'
